 6: 
 7: - name: Fail if required WeChat settings not defined
 8:   ansible.builtin.fail:
 9:     msg: >-
10:       You need to define a required configuration setting (`{{ item.name }}`).
11:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
12:   with_items:
13:     - {'name': 'matrix_bridge_wechat_appservice_token', when: true}
14:     - {'name': 'matrix_bridge_wechat_homeserver_address', when: true}
15:     - {'name': 'matrix_bridge_wechat_homeserver_token', when: true}
16:     - {'name': 'matrix_bridge_wechat_database_hostname', when: "{{ matrix_bridge_wechat_database_engine == 'postgres' }}"}
17:     - {'name': 'matrix_bridge_wechat_container_network', when: true}
18:     - {'name': 'matrix_bridge_wechat_bridge_listen_secret', when: true}
19: 
20: - name: Fail if WeChat enabled on ARM64 (not supported by the wechat agent, even with self-building)
21:   when: matrix_architecture not in ['amd64']
22:   ansible.builtin.fail:
23:     msg: "The WeChat Agent does not support the '{{ matrix_architecture }}' architecture yet. Its Dockerfile downloads amd64 binaries and does not work on arm64."
24: 
25: - name: (Deprecation) Catch and report renamed WeChat variables
26:   ansible.builtin.fail:
27:     msg: >-
28:       The variable `{{ item.old }}` is deprecated. Please use `{{ item.new }}` instead.
29:   when: "lookup('ansible.builtin.varnames', ('^' + item.old + '$'), wantlist=True) | length > 0"
30:   with_items:
31:     - {'old': 'matrix_bridge_wechat_container_image_name_prefix', 'new': 'matrix_bridge_wechat_container_image_registry_prefix'}
32:     - {'old': 'matrix_bridge_wechat_agent_container_image_name_prefix', 'new': 'matrix_bridge_wechat_agent_container_image_registry_prefix'}
33:     - {'old': 'matrix_bridge_wechat_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
34:     - {'old': 'matrix_bridge_wechat_agent_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
